"""Native feasibility adapter for same-turn Jev request consolidation.
Evaluation only. It is not installed or registered by Switchyard.
"""
from __future__ import annotations
import copy
import contextvars
import threading
import time
from .client import DecisionClient
from .reasoning_effort_adapter import _task_scan, choose_reasoning_effort

ACTIVE = None
PRE = contextvars.ContextVar("consolidation_pre", default=None)
WIRE = contextvars.ContextVar("consolidation_wire", default=None)

class Capture:
    def decide(self,state,questions,**kwargs):
        self.parts=copy.deepcopy((state,questions))
        raise RuntimeError("capture only")

class Replay:
    def __init__(self,result):
        self.result=result
    def decide(self,state,questions,**kwargs):
        return {**self.result,"answers":{k:self.result["answers"][k] for k in questions}}

def effort_parts(task,cap):
    c=Capture()
    levels=["low","medium","high"][:["low","medium","high"].index(cap)+1]
    choose_reasoning_effort(task=task,recent_tool_outcomes=[],client=c,
        requested_effort=cap,allowed_efforts=levels,deadline_seconds=.4)
    return c.parts

class Broker:
    def __init__(self):
        self.records={}
        self.lock=threading.Lock()
        self.receipts=[]
    def clear(self,key):
        with self.lock:self.records.pop(key,None)
    def store(self,key,record):
        with self.lock:
            if len(self.records)>=32:self.records.pop(next(iter(self.records)))
            self.records[key]=record
    def consume(self,key,capture,requested,candidates,controller):
        if key is None or capture is None or capture.get("scan_reason") or capture.get("metadata"):
            return None
        if not controller.public_or_sanitized_data_ack:
            return None
        expected={"medium":["low","medium"],"high":["low","medium","high"]}.get(requested)
        if expected is None or list(candidates)!=expected:
            return None
        with self.lock:record=self.records.pop(key,None)
        if record is None or record["task"]!=capture.get("excerpt"):
            return None
        if record["wall_ms"]>controller.deadline_seconds*1000 or time.monotonic()-record["at"]>30:
            return None
        result=copy.deepcopy(record["result"])
        result["answers"]["reasoning_effort"]=result["answers"]["reasoning_effort_"+requested]
        choice=choose_reasoning_effort(task=record["task"],recent_tool_outcomes=[],
            client=Replay(result),requested_effort=requested,allowed_efforts=candidates,
            public_or_sanitized_data_ack=True,deadline_seconds=.4)
        if choice.get("status")!="selected":
            return None
        self.receipts.append({"shared_request_id":result.get("request_id"),
            "cap":requested,"effort":choice["effort"],"shared_latency_ms":record["wall_ms"]})
        # Count the physical request in skill routing only; this is an experiment
        # with user receipt lines disabled, not a shipped receipt schema.
        return {**choice,"jev_called":False,"jev_latency_ms":record["wall_ms"],
                "shared_decision":True}

class JointClient(DecisionClient):
    def decide(self,state,questions,**kwargs):
        scope=PRE.get()
        if scope is None or not isinstance(state,dict) or state.get("stage")==2:
            return super().decide(state,questions,**kwargs)
        task=state.get("task")
        if task!=scope["task"] or not ("skill" in questions or "skill_chunk_0" in questions):
            return super().decide(state,questions,**kwargs)
        qs=copy.deepcopy(questions)
        merged_state=copy.deepcopy(state)
        for cap in ["medium","high"]:
            es,eq=effort_parts(task,cap)
            merged_state.update({k:v for k,v in es.items() if k!="current_request"})
            qs["reasoning_effort_"+cap]={**eq["reasoning_effort"],
                "instructions":eq["reasoning_effort"]["instructions"].replace("current_request","task")}
        qs["stakes"]={**eq["stakes"],"instructions":eq["stakes"]["instructions"].replace("current_request","task")}
        started=time.perf_counter()
        result=super().decide(merged_state,qs,**kwargs)
        elapsed=(time.perf_counter()-started)*1000
        scope["broker"].store(scope["key"],{"task":task,"result":copy.deepcopy(result),
            "at":time.monotonic(),"wall_ms":elapsed})
        return {**result,"answers":{k:result["answers"][k] for k in questions}}

class ContextProxy:
    def __init__(self,ctx):
        global ACTIVE
        self.ctx=ctx
        self.broker=Broker()
        ACTIVE=self.broker
        from . import __name__ as package_name
        import sys
        # Only the isolated prototype's factory is changed; the host stays intact.
        sys.modules[package_name].DecisionClient=JointClient
    def __getattr__(self,name):
        return getattr(self.ctx,name)
    def register_hook(self,kind,callback):
        if kind!="pre_llm_call" or not callback.__module__.endswith(".automatic"):
            return self.ctx.register_hook(kind,callback)
        def wrapped(**context):
            key=tuple(context.get(k) for k in ["session_id","task_id","turn_id"])
            self.broker.clear(key)
            task=context.get("user_message")
            clean,reason=_task_scan(task)
            eligible=(all(isinstance(k,str) and k.strip() for k in key)
                and isinstance(task,str) and len(task)<=1200 and clean==task and not reason
                and context.get("platform")=="cli" and not context.get("parent_session_id")
                and context.get("model")=="gpt-6-sol")
            token=PRE.set({"key":key,"task":clean,"broker":self.broker} if eligible else None)
            try:return callback(**context)
            finally:PRE.reset(token)
        return self.ctx.register_hook(kind,wrapped)
    def register_middleware(self,kind,callback):
        controller=getattr(callback,"__self__",None)
        if kind!="llm_request" or controller is None or not hasattr(controller,"_ask_jev"):
            return self.ctx.register_middleware(kind,callback)
        original=controller._ask_jev
        def ask(state,capture,requested,candidates,**kw):
            shared=None
            if not state.outcomes and kw.get("step_kinds") is None:
                shared=self.broker.consume(WIRE.get(),capture,requested,candidates,controller)
            return shared if shared is not None else original(state,capture,requested,candidates,**kw)
        controller._ask_jev=ask
        def wrapped(request=None,**context):
            key=tuple(context.get(k) for k in ["session_id","task_id","turn_id"])
            supported=context.get("provider")=="openai-codex" and context.get("api_mode")=="codex_responses"
            token=WIRE.set(key if supported else None)
            try:return callback(request=request,**context)
            finally:WIRE.reset(token)
        return self.ctx.register_middleware(kind,wrapped)

hermes_switchyard/client.py:
"""Fixed-route OpenRouter Decisions API client for Jev."""
from __future__ import annotations

import email.utils
import http.client
import inspect
import json
import logging
import math
import ssl
import threading
import time
import urllib.error
import urllib.parse
import urllib.request
from contextlib import AbstractContextManager, contextmanager, nullcontext
from contextvars import ContextVar
from collections.abc import Callable
from typing import Any, cast

from . import receipt_state

logger = logging.getLogger(__name__)

DEFAULT_ENDPOINT = "https://openrouter.ai/api/alpha/decisions"
TYPESAFE_ENDPOINT = "https://api.typesafe.ai/v1/systemone"
OPENROUTER_APP_HEADERS = {
    "HTTP-Referer": "https://github.com/bgrablin/hermes-switchyard",
    "X-Title": "Hermes-Switchyard",
    "X-OpenRouter-Title": "Hermes-Switchyard",
    "X-OpenRouter-Categories": "personal-agent,cli-agent",
}
OPENROUTER_MODELS = frozenset({"typesafe/jev-1.13", "typesafe/jev-1.13-20260917"})
TYPESAFE_MODELS = frozenset({"jev-latest", "jev-1.13", "jev-1.13.0"})
ALLOWED_ENDPOINTS = frozenset({DEFAULT_ENDPOINT, TYPESAFE_ENDPOINT})
ALLOWED_MODELS = OPENROUTER_MODELS | TYPESAFE_MODELS
EXPECTED_MODEL = "typesafe/jev-1.13"
MAX_QUESTIONS_PER_REQUEST = 255
MAX_REQUEST_BYTES = 96_000
MAX_RESPONSE_BYTES = 1_048_576
MAX_ERROR_BYTES = 16_384
MAX_DECISION_REQUESTS = 64
MAX_TOTAL_QUESTIONS = MAX_QUESTIONS_PER_REQUEST * MAX_DECISION_REQUESTS
MAX_OPERATION_REQUESTS = 256
DEFAULT_OPERATION_DEADLINE_SECONDS = 60.0
# Automatic pre_llm_call advice must finish before a typical Hermes plugin
# callback budget (~30s). Keep this comfortably below that host timeout and
# separate from explicit decision / computer-use deadlines (60s).
DEFAULT_AUTOMATIC_ROUTING_DEADLINE_SECONDS = 20.0
# Conservatively replace a pooled connection after 60 s idle to avoid reusing
# a socket that may have closed server-side. No live idle-close threshold has
# been measured for this route (issue #92).
MAX_CONNECTION_IDLE_SECONDS = 60.0
# Errors that mean the server closed a reused keep-alive connection before it
# sent any response. RemoteDisconnected is a ConnectionResetError; it is listed
# for clarity. Timeouts are not in this set and are never replayed.
_STALE_CONNECTION_ERRORS = (
    http.client.RemoteDisconnected,
    ConnectionResetError,
    ConnectionAbortedError,
    BrokenPipeError,
    ssl.SSLEOFError,
)
# HTTP 429 (rate limited) and 529 (overloaded) mean the provider did not run
# the request. A decision request is a pure function of its inputs, so a
# bounded replay is safe. Each retry waits for the larger of the exponential
# backoff and a numeric or HTTP-date ``Retry-After`` value. A retry is not
# started when the wait exceeds MAX_RETRY_AFTER_SECONDS or would leave less
# than MIN_RETRY_REMAINING_SECONDS of the operation deadline.
RETRYABLE_HTTP_STATUSES = frozenset({429, 529})
MAX_RATE_LIMIT_RETRIES = 2
RATE_LIMIT_BACKOFF_BASE_SECONDS = 0.5
MAX_RETRY_AFTER_SECONDS = 8.0
MIN_RETRY_REMAINING_SECONDS = 1.0
_RETRY_SLEEP_SLICE_SECONDS = 0.25
# Transport retries (stale connection plus 429/529) across one bounded
# operation scope. Each logical request also has its own per-request bound.
MAX_OPERATION_RETRIES = 4
# Closed set of safe diagnostic sub-codes for a hosted request failure. No
# provider text, header value, URL, or payload data is ever part of a code.
HOSTED_ERROR_DETAILS = receipt_state.HOSTED_ERROR_DETAILS
# Closed set of retry reasons recorded in call metadata.
TRANSPORT_RETRY_REASONS = frozenset({"stale_connection", "http_429", "http_529"})
# A default log shows at most one WARNING per failure sub-code per interval.
HOSTED_FAILURE_WARNING_INTERVAL_SECONDS = 300.0
_WARNING_LOCK = threading.Lock()
_WARNING_LAST: dict[str, float] = {}
_WARNING_SUPPRESSED: dict[str, int] = {}

_RESPONSE_FIELDS = frozenset({"model", "answers", "usage", "latency_ms", "request_id"})
_OPERATION_DEADLINE: ContextVar[float | None] = ContextVar(
    "jev_operation_deadline", default=None
)
_HOST_CANCEL_CHECK: ContextVar[Any] = ContextVar(
    "jev_host_cancel_check", default=None
)
_DEFER_HOSTED_WARNING: ContextVar[bool] = ContextVar(
    "jev_defer_hosted_warning", default=False
)


class DeadlineExceeded(TimeoutError):
    """Aggregate operation wall-clock deadline expired before or between requests."""


class LateResultDiscarded(TimeoutError):
    """Provider work finished after the consumer deadline; the result must not be used."""


class HostCancelled(TimeoutError):
    """Host abandoned the plugin callback; stop further requests."""


class JevRequestError(RuntimeError):
    """A hosted request failure with a closed-set diagnostic sub-code.

    The message keeps the stable local wording used before. ``detail`` is one
    member of HOSTED_ERROR_DETAILS and never carries provider text.
    """

    def __init__(self, message: str, *, detail: str) -> None:
        super().__init__(message)
        self.detail = detail if detail in HOSTED_ERROR_DETAILS else "unknown"


def _http_status_detail(status: int) -> str:
    if status in (401, 403, 404, 429, 529):
        return f"http_{status}"
    if 300 <= status < 400:
        return "redirect"
    if 400 <= status < 500:
        return "http_4xx"
    return "http_5xx"


def hosted_error_detail(exc: BaseException | None) -> str:
    """Map a hosted failure to one closed-set diagnostic sub-code.

    This is a pure function of the exception type and of the typed ``detail``
    set by this module. It never reads provider text.
    """
    seen = 0
    while exc is not None and seen < 8:
        seen += 1
        if isinstance(exc, PartialAccountingError) and exc.__cause__ is not None:
            exc = exc.__cause__
            continue
        if isinstance(exc, JevRequestError):
            return exc.detail
        if isinstance(exc, HostCancelled):
            return "host_cancelled"
        if isinstance(exc, LateResultDiscarded):
            return "late_result_discarded"
        if isinstance(exc, DeadlineExceeded):
            return "deadline_exceeded"
        if isinstance(exc, PermissionError):
            return "ack_required"
        if isinstance(exc, TimeoutError):
            return "timeout"
        if isinstance(exc, ValueError):
            if "budget exceeded" in str(exc):
                return "request_budget_exhausted"
            return "validation_failure"
        if isinstance(exc, TypeError):
            return "invalid_response"
        if isinstance(exc, (ConnectionError, ssl.SSLError)):
            return "connect_failed"
        return "unknown"
    return "unknown"


def _warn_hosted_failure(detail: str) -> None:
    """Log one WARNING per sub-code per interval; count the suppressed ones."""
    if detail == "host_cancelled":
        return
    now = time.monotonic()
    with _WARNING_LOCK:
        last = _WARNING_LAST.get(detail)
        if last is not None and now - last < HOSTED_FAILURE_WARNING_INTERVAL_SECONDS:
            _WARNING_SUPPRESSED[detail] = _WARNING_SUPPRESSED.get(detail, 0) + 1
            return
        suppressed = _WARNING_SUPPRESSED.pop(detail, 0)
        _WARNING_LAST[detail] = now
    logger.warning(
        "Jev hosted request failed (%s); %d similar failures suppressed since the last warning.",
        detail,
        suppressed,
    )


def _reset_warning_rate_limit() -> None:
    """Clear warning rate-limit state (tests only)."""
    with _WARNING_LOCK:
        _WARNING_LAST.clear()
        _WARNING_SUPPRESSED.clear()


@contextmanager
def _defer_hosted_warning():
    """Let an enclosing automatic turn warn once, including pre-decision failures."""
    token = _DEFER_HOSTED_WARNING.set(True)
    try:
        yield
    finally:
        _DEFER_HOSTED_WARNING.reset(token)


def parse_retry_after(value: Any, *, now: float | None = None) -> float | None:
    """Return a non-negative Retry-After delay in seconds, or None if invalid.

    Accepts delta-seconds or an HTTP-date. The value is parsed locally and is
    never logged or stored.
    """
    if type(value) is not str:
        return None
    text = value.strip()
    if not text or len(text) > 64:
        return None
    if text.isascii() and text.isdigit():
        return float(int(text))
    try:
        when = email.utils.parsedate_to_datetime(text)
    except (TypeError, ValueError, IndexError, OverflowError):
        return None
    if when is None or when.tzinfo is None:
        return None
    current = time.time() if now is None else now
    return max(0.0, when.timestamp() - current)


def merge_transport_retries(total: dict[str, int], retries: Any) -> None:
    """Add closed-set retry counts from ``retries`` into ``total``."""
    if not isinstance(retries, dict):
        return
    for reason, count in retries.items():
        if reason in TRANSPORT_RETRY_REASONS and type(count) is int and 0 < count <= MAX_OPERATION_RETRIES * 1024:
            total[reason] = total.get(reason, 0) + count


def _validate_deadline_seconds(value: Any) -> float:
    if type(value) not in (int, float) or not math.isfinite(value) or value <= 0:
        raise ValueError("deadline_seconds must be a finite positive number")
    return float(value)


@contextmanager
def operation_deadline_scope(deadline_seconds: float | None):
    """Install one monotonic deadline for every bounded operation layer."""
    if deadline_seconds is None:
        yield
        return
    duration = _validate_deadline_seconds(deadline_seconds)
    current = _OPERATION_DEADLINE.get()
    candidate = time.monotonic() + duration
    effective = candidate if current is None else min(current, candidate)
    token = _OPERATION_DEADLINE.set(effective)
    try:
        yield
    finally:
        _OPERATION_DEADLINE.reset(token)


@contextmanager
def host_cancel_scope(cancel_check: Callable[[], bool] | None):
    """Install an optional host-cancel predicate for cooperative abort."""
    if cancel_check is None:
        yield
        return
    token = _HOST_CANCEL_CHECK.set(cancel_check)
    try:
        yield
    finally:
        _HOST_CANCEL_CHECK.reset(token)


def operation_remaining_deadline() -> float | None:
    """Return remaining aggregate time, or raise once the operation expires.

    Also raises ``HostCancelled`` when an installed host-cancel check reports
    that the consumer abandoned the callback.
    """
    cancel_check = _HOST_CANCEL_CHECK.get()
    if callable(cancel_check):
        try:
            cancelled = bool(cancel_check())
        except Exception:  # noqa: BLE001 -- cancel probes must not mask deadlines
            cancelled = False
        if cancelled:
            raise HostCancelled("host cancelled the plugin callback")
    deadline = _OPERATION_DEADLINE.get()
    if deadline is None:
        return None
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise DeadlineExceeded("Jev aggregate deadline exceeded")
    return remaining


def _request_budget_context(
    factory: Callable[..., Any], max_requests: int, deadline_seconds: float | None
):
    if deadline_seconds is None:
        return factory(max_requests)
    try:
        parameters = inspect.signature(factory).parameters.values()
    except (TypeError, ValueError):
        parameters = ()
    supports_deadline = any(
        parameter.name == "deadline_seconds"
        or parameter.kind is inspect.Parameter.VAR_KEYWORD
        for parameter in parameters
    )
    if supports_deadline:
        return factory(max_requests, deadline_seconds=deadline_seconds)
    return factory(max_requests)


def request_budget_scope(
    client: Any,
    max_requests: int = MAX_DECISION_REQUESTS,
    *,
    deadline_seconds: float | None = None,
) -> AbstractContextManager[None]:
    @contextmanager
    def scoped_operation():
        with operation_deadline_scope(deadline_seconds):
            factory = getattr(client, "request_budget", None)
            if not callable(factory):
                with nullcontext():
                    yield
                return
            scoped = _request_budget_context(factory, max_requests, deadline_seconds)
            with cast(AbstractContextManager[None], scoped):
                yield

    return scoped_operation()


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON constant {value!r} is not allowed")


def _reject_duplicate_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def _strict_json_loads(raw: bytes) -> Any:
    return json.loads(
        raw,
        object_pairs_hook=_reject_duplicate_pairs,
        parse_constant=_reject_json_constant,
    )


def _parse_error_body(raw: bytes) -> None:
    """Validate JSON error envelopes without retaining provider-controlled text."""
    if not raw or not raw.strip():
        return
    try:
        parsed = _strict_json_loads(raw)
    except (TypeError, ValueError, json.JSONDecodeError):
        # Plain-text HTTP errors are tolerated, but JSON-looking error bodies
        # must satisfy the same duplicate/non-finite boundary as success data.
        if raw.lstrip().startswith((b"{", b"[")):
            raise RuntimeError("Jev provider returned invalid error JSON") from None
        return
    if not isinstance(parsed, dict):
        raise RuntimeError("Jev provider returned an invalid error envelope")
    _reject_nonfinite_values(parsed)


def _reject_nonfinite_values(value: Any) -> None:
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("non-finite JSON number is not allowed")
    if isinstance(value, dict):
        for key, item in value.items():
            if type(key) is not str:
                raise TypeError("JSON object keys must be strings")
            _reject_nonfinite_values(item)
    elif isinstance(value, (list, tuple)):
        for item in value:
            _reject_nonfinite_values(item)


def _strip_response_controls(result: dict[str, Any]) -> dict[str, Any]:
    """Keep only the typed response envelope; provider controls stay local."""
    _reject_nonfinite_values(result)
    # OpenRouter's documented Decisions response carries its request identifier
    # as `id`; older fixtures use `request_id`. Normalize to the canonical
    # internal field before the allowlist drops unknown wire fields. Exactly one
    # identifier may be present; contradictory dual identifiers are rejected
    # rather than resolved silently.
    wire_id = result.get("id")
    canonical_id = result.get("request_id")
    if wire_id is not None:
        if type(wire_id) is not str or not 0 < len(wire_id) <= 128 or not wire_id.isprintable():
            raise ValueError("Jev response identifier is not a bounded printable string")
        if canonical_id is not None and canonical_id != wire_id:
            raise ValueError("Jev response carries contradictory identifiers")
        canonical_id = wire_id
    stripped = {key: result[key] for key in _RESPONSE_FIELDS if key in result}
    if canonical_id is not None:
        stripped["request_id"] = canonical_id
    return stripped


def _require_public_data_ack(acknowledged: bool = True) -> None:
    if acknowledged is not True:
        raise PermissionError(
            "public_or_sanitized_data_ack is false; this call was refused"
        )


def _valid_model_slug(model: Any, endpoint: str | None = None) -> bool:
    if type(model) is not str:
        return False
    if endpoint == DEFAULT_ENDPOINT:
        return model in OPENROUTER_MODELS
    if endpoint == TYPESAFE_ENDPOINT:
        return model in TYPESAFE_MODELS
    return model in ALLOWED_MODELS


class _NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    """Reject all redirects so a bearer token cannot be forwarded elsewhere."""

    @staticmethod
    def _reject(request, _fp, code, _message, headers):
        raise urllib.error.HTTPError(request.full_url, code, "redirects disabled", headers, None)

    http_error_301 = _reject
    http_error_302 = _reject
    http_error_303 = _reject
    http_error_307 = _reject
    http_error_308 = _reject


class PartialAccountingError(RuntimeError):
    """Raised when a later request fails after earlier responses were recorded.

    Carries the bounded ledger of responses observed before the failure so the
    caller can surface honest accounting (request IDs, usage, timing) at the
    terminal boundary instead of discarding earlier successful attempts.
    """

    def __init__(self, message: str, *, partial: list[dict[str, Any]]) -> None:
        super().__init__(message)
        self.partial = list(partial)


class DecisionClient:
    """Call one of the fixed Jev endpoints and require exact model resolution."""

    def __init__(
        self,
        *,
        api_key: str,
        endpoint: str = DEFAULT_ENDPOINT,
        model: str = EXPECTED_MODEL,
        timeout: float = 25,
        transport: Callable[[dict], dict] | None = None,
        max_connection_idle_seconds: float = MAX_CONNECTION_IDLE_SECONDS,
    ):
        if type(api_key) is not str or not api_key.strip():
            raise ValueError("Jev API key is required")
        if endpoint not in ALLOWED_ENDPOINTS:
            raise ValueError("Jev endpoint is not an evidence-backed fixed endpoint")
        if not _valid_model_slug(model, endpoint):
            raise ValueError("Jev model is not an evidence-backed allowed alias for this endpoint")
        if type(timeout) not in (int, float) or not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("timeout must be a finite positive number")
        if (
            type(max_connection_idle_seconds) not in (int, float)
            or not math.isfinite(max_connection_idle_seconds)
            or not 0 < max_connection_idle_seconds <= 3600
        ):
            raise ValueError("max_connection_idle_seconds must be between 0 and 3600")
        self.api_key = api_key
        self.endpoint = endpoint
        self.model = model
        self.timeout = float(timeout)
        self.max_connection_idle_seconds = float(max_connection_idle_seconds)
        self.transport = transport
        self._url = urllib.parse.urlsplit(endpoint)
        self._connection: http.client.HTTPSConnection | None = None
        self._connection_last_used: float | None = None
        # Count of requests replayed after a pooled connection was found closed.
        self.stale_connection_retries = 0
        # Count of requests replayed after HTTP 429 or 529.
        self.rate_limit_retries = 0
        self._connection_lock = threading.RLock()
        self._request_budget: ContextVar[int | None] = ContextVar(
            f"jev_request_budget_{id(self)}", default=None
        )
        # Transport retries left in the current bounded operation scope.
        self._retry_budget: ContextVar[list[int] | None] = ContextVar(
            f"jev_retry_budget_{id(self)}", default=None
        )
        # Closed-set retry counts for the logical request in progress.
        self._call_retries: ContextVar[dict[str, int] | None] = ContextVar(
            f"jev_call_retries_{id(self)}", default=None
        )
        self._operation_deadline: ContextVar[float | None] = ContextVar(
            f"jev_operation_deadline_{id(self)}", default=None
        )

    @contextmanager
    def request_budget(
        self,
        max_requests: int = MAX_DECISION_REQUESTS,
        *,
        deadline_seconds: float | None = None,
    ):
        if type(max_requests) is not int or not 1 <= max_requests <= MAX_OPERATION_REQUESTS:
            raise ValueError("max_requests is outside the bounded operation budget")
        if deadline_seconds is not None and (
            type(deadline_seconds) not in (int, float)
            or not math.isfinite(deadline_seconds)
            or deadline_seconds <= 0
        ):
            raise ValueError("deadline_seconds must be a finite positive number")
        current = self._request_budget.get()
        if current is not None:
            yield
            return
        token = self._request_budget.set(max_requests)
        retry_token = self._retry_budget.set([MAX_OPERATION_RETRIES])
        deadline_token = self._operation_deadline.set(
            time.monotonic() + float(deadline_seconds)
            if deadline_seconds is not None
            else None
        )
        try:
            yield
        finally:
            self._request_budget.reset(token)
            self._retry_budget.reset(retry_token)
            self._operation_deadline.reset(deadline_token)

    def _remaining_deadline(self) -> float | None:
        remaining = operation_remaining_deadline()
        deadline = self._operation_deadline.get()
        if deadline is not None:
            local_remaining = deadline - time.monotonic()
            if local_remaining <= 0:
                raise DeadlineExceeded("Jev aggregate deadline exceeded")
            remaining = local_remaining if remaining is None else min(remaining, local_remaining)
        return remaining

    def _close_connection(self) -> None:
        self._connection_last_used = None
        if self._connection is not None:
            try:
                self._connection.close()
            finally:
                self._connection = None

    def _connection_idle_too_long(self) -> bool:
        last_used = self._connection_last_used
        return last_used is not None and time.monotonic() - last_used > self.max_connection_idle_seconds

    def _take_retry(self, reason: str) -> bool:
        """Reserve one transport retry from the operation budget and record it."""
        budget = self._retry_budget.get()
        if budget is not None:
            if budget[0] <= 0:
                return False
            budget[0] -= 1
        call_retries = self._call_retries.get()
        if call_retries is not None:
            call_retries[reason] = call_retries.get(reason, 0) + 1
        return True

    def _send_request(
        self,
        path: str,
        body: bytes,
        headers: dict[str, str],
        *,
        allow_stale_retry: bool = True,
    ) -> tuple[Any, bool]:
        """Send one POST; return the response and whether a stale retry ran.

        Call with the connection lock held. A pooled keep-alive connection
        that the server closed while idle fails before any response byte
        arrives. Only that case is retried, once, on a new connection. A
        decision request changes no provider state, so the replay is safe. A
        failure on a new connection, a timeout, and any failure after the
        response started are raised unchanged.
        """
        stale_retried = False
        for attempt in range(2):
            remaining = self._remaining_deadline()
            timeout = self.timeout if remaining is None else min(self.timeout, remaining)
            if self._connection is not None and self._connection_idle_too_long():
                self._close_connection()
            reused = self._connection is not None
            if self._connection is None:
                host = self._url.hostname
                if not host:
                    raise JevRequestError("Jev endpoint has no host", detail="transport_failed")
                self._connection = http.client.HTTPSConnection(
                    host,
                    self._url.port,
                    timeout=timeout,
                )
            elif getattr(self._connection, "sock", None) is not None:
                self._connection.sock.settimeout(timeout)
            try:
                self._connection.request("POST", path, body=body, headers=headers)
                return self._connection.getresponse(), stale_retried
            except _STALE_CONNECTION_ERRORS as exc:
                self._close_connection()
                if stale_retried:
                    raise JevRequestError(
                        f"Jev connection failed: {type(exc).__name__}", detail="stale_connection"
                    ) from None
                if not reused or not allow_stale_retry or attempt or not self._take_retry("stale_connection"):
                    raise JevRequestError(
                        f"Jev connection failed: {type(exc).__name__}", detail="connect_failed"
                    ) from None
                stale_retried = True
                self.stale_connection_retries += 1
                logger.info(
                    "Jev pooled connection was closed by the server (%s); retrying once on a new connection.",
                    type(exc).__name__,
                )
        raise JevRequestError("Jev connection retry did not complete", detail="stale_connection")

    @staticmethod
    def _read_bounded(response: Any, limit: int) -> bytes:
        headers = getattr(response, "headers", None)
        content_length = None
        if headers is not None:
            try:
                content_length = headers.get("Content-Length")
            except AttributeError:
                content_length = None
        if content_length is not None:
            try:
                declared = int(content_length)
            except (TypeError, ValueError):
                raise RuntimeError("Jev provider returned an invalid response length") from None
            if declared < 0 or declared > limit:
                raise RuntimeError("Jev provider response exceeded the bounded body limit")
        try:
            raw = response.read(limit + 1)
        except TypeError:
            # Test transports and old HTTPResponse shims may only expose read().
            raw = response.read()
        if not isinstance(raw, (bytes, bytearray)):
            raise RuntimeError("Jev provider returned an invalid response body")
        if len(raw) > limit:
            raise RuntimeError("Jev provider response exceeded the bounded body limit")
        return bytes(raw)

    def _retry_delay(self, status: int, retry_after: Any, retries_done: int) -> float | None:
        """Return a bounded wait before a 429/529 retry, or None to stop."""
        if retries_done >= MAX_RATE_LIMIT_RETRIES:
            return None
        delay = RATE_LIMIT_BACKOFF_BASE_SECONDS * (2 ** retries_done)
        parsed = parse_retry_after(retry_after)
        if parsed is not None:
            if parsed > MAX_RETRY_AFTER_SECONDS:
                return None
            delay = max(delay, parsed)
        delay = min(delay, MAX_RETRY_AFTER_SECONDS)
        remaining = self._remaining_deadline()
        if remaining is not None and delay + MIN_RETRY_REMAINING_SECONDS > remaining:
            return None
        return delay

    def _sleep_before_retry(self, delay: float) -> None:
        """Sleep in short slices so a deadline or host cancel stops the wait."""
        end = time.monotonic() + delay
        while True:
            self._remaining_deadline()
            left = end - time.monotonic()
            if left <= 0:
                return
            time.sleep(min(_RETRY_SLEEP_SLICE_SECONDS, left))

    def _post_attempt(
        self, path: str, body: bytes, headers: dict[str, str], *, allow_stale_retry: bool
    ) -> tuple[bytes | None, int | None, Any, bool]:
        """Run one HTTP exchange under the connection lock.

        Returns ``(raw, None, None, stale_retried)`` on success, or
        ``(None, status, retry_after, stale_retried)`` for a retryable 429/529.
        """
        with self._connection_lock:
            stale_retried = False
            try:
                response, stale_retried = self._send_request(
                    path, body, headers, allow_stale_retry=allow_stale_retry
                )
                status = response.status
                if 300 <= status < 400:
                    _parse_error_body(self._read_bounded(response, MAX_ERROR_BYTES))
                    raise JevRequestError(
                        "Jev provider returned an unexpected redirect", detail="redirect"
                    )
                if status >= 400:
                    if status in RETRYABLE_HTTP_STATUSES:
                        retry_after = None
                        response_headers = getattr(response, "headers", None)
                        if response_headers is not None:
                            try:
                                retry_after = response_headers.get("Retry-After")
                            except AttributeError:
                                retry_after = None
                        # Status and headers suffice. Do not parse an untrusted
                        # error body before a bounded 429/529 retry.
                        try:
                            close_response = getattr(response, "close", None)
                            if callable(close_response):
                                close_response()
                        finally:
                            self._close_connection()
                        return None, status, retry_after, stale_retried
                    _parse_error_body(self._read_bounded(response, MAX_ERROR_BYTES))
                    raise JevRequestError(
                        f"Jev provider returned HTTP {status}",
                        detail=_http_status_detail(status),
                    )
                raw = self._read_bounded(response, MAX_RESPONSE_BYTES)
                self._connection_last_used = time.monotonic()
                if getattr(response, "will_close", False):
                    self._close_connection()
                close_response = getattr(response, "close", None)
                if callable(close_response):
                    close_response()
                return raw, None, None, stale_retried
            except JevRequestError:
                self._close_connection()
                raise
            except RuntimeError as exc:
                self._close_connection()
                raise JevRequestError(str(exc), detail="invalid_response") from None
            except TimeoutError:
                self._close_connection()
                raise
            except (OSError, http.client.HTTPException) as exc:
                self._close_connection()
                detail = "invalid_response" if isinstance(exc, http.client.HTTPException) else "connect_failed"
                raise JevRequestError(
                    f"Jev connection failed: {type(exc).__name__}", detail=detail
                ) from None

    def _post(self, payload: dict) -> dict:
        self._remaining_deadline()
        if self.transport is not None:
            try:
                result = self.transport(payload)
            except (DeadlineExceeded, LateResultDiscarded, HostCancelled):
                raise
            except TimeoutError:
                raise
            except Exception as exc:  # noqa: BLE001 - never expose transport/payload details
                raise JevRequestError(
                    f"Jev transport failed: {type(exc).__name__}", detail="transport_failed"
                ) from None
            try:
                self._remaining_deadline()
            except DeadlineExceeded as exc:
                # The consumer can no longer use this response. Discard it and
                # record a distinct late-result outcome rather than publishing.
                raise LateResultDiscarded(
                    "Jev late result discarded after aggregate deadline"
                ) from exc
            if not isinstance(result, dict):
                raise TypeError("Jev transport returned a non-object response")
            return _strip_response_controls(result)
        try:
            body = json.dumps(payload, ensure_ascii=False, allow_nan=False).encode("utf-8")
        except (TypeError, ValueError):
            raise ValueError("Jev request contains a non-JSON value") from None
        path = self._url.path or "/"
        if self._url.query:
            path += f"?{self._url.query}"
        headers = {
            "Authorization": "Bearer " + self.api_key,
            "Content-Type": "application/json",
            "Connection": "keep-alive",
        }
        if self.endpoint == DEFAULT_ENDPOINT:
            headers.update(OPENROUTER_APP_HEADERS)
        allow_stale_retry = True
        rate_retries = 0
        while True:
            raw, status, retry_after, stale_retried = self._post_attempt(
                path, body, headers, allow_stale_retry=allow_stale_retry
            )
            if stale_retried:
                # At most one stale-connection replay per logical request.
                allow_stale_retry = False
            if raw is not None:
                break
            assert status is not None
            detail = _http_status_detail(status)
            delay = self._retry_delay(status, retry_after, rate_retries)
            if delay is None:
                raise JevRequestError(f"Jev provider returned HTTP {status}", detail=detail)
            if not self._take_retry(detail):
                raise JevRequestError(
                    f"Jev provider returned HTTP {status}", detail="retry_budget_exhausted"
                )
            rate_retries += 1
            self.rate_limit_retries += 1
            logger.info(
                "Jev provider returned HTTP %d; retry %d of %d after %.2f s.",
                status,
                rate_retries,
                MAX_RATE_LIMIT_RETRIES,
                delay,
            )
            self._sleep_before_retry(delay)
        try:
            self._remaining_deadline()
        except DeadlineExceeded as exc:
            raise LateResultDiscarded(
                "Jev late result discarded after aggregate deadline"
            ) from exc
        try:
            result = _strict_json_loads(raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            raise JevRequestError(
                "Jev provider returned invalid JSON", detail="invalid_response"
            ) from None
        if not isinstance(result, dict):
            raise TypeError("Jev provider returned a non-object response")
        return _strip_response_controls(result)

    def _validate_resolved_model(self, resolved: Any) -> str:
        if not _valid_model_slug(resolved, self.endpoint):
            raise ValueError("Jev provider resolved a model outside the allowed aliases")
        # Aliases may resolve to a dated/concrete release, but an explicitly
        # pinned model must resolve exactly to that model.
        if self.endpoint == DEFAULT_ENDPOINT and self.model == EXPECTED_MODEL and resolved in OPENROUTER_MODELS:
            return resolved
        if self.endpoint == TYPESAFE_ENDPOINT and self.model == "jev-latest" and resolved in TYPESAFE_MODELS:
            return resolved
        if resolved != self.model:
            raise ValueError("Jev provider resolved a different allowed alias")
        return resolved

    @staticmethod
    def _validate_usage(usage: Any) -> dict[str, Any]:
        if not isinstance(usage, dict):
            raise TypeError("Jev response usage must be an object")
        if "cost" in usage:
            cost = usage["cost"]
            if type(cost) not in (int, float) or not math.isfinite(cost) or cost < 0:
                raise ValueError("Invalid Jev usage cost")
        return receipt_state.safe_usage(usage)

    @staticmethod
    def _validate_questions(questions: Any) -> dict[str, dict[str, Any]]:
        if not isinstance(questions, dict) or not questions:
            raise ValueError("questions must be a non-empty object")
        if len(questions) > MAX_TOTAL_QUESTIONS:
            raise ValueError("question count exceeds the bounded provider-request budget")
        validated: dict[str, dict[str, Any]] = {}
        for name, question in questions.items():
            if type(name) is not str or not name or name != name.strip():
                raise ValueError("question names must be non-empty exact strings")
            if not isinstance(question, dict) or set(question) - {"type", "instructions", "criteria"}:
                raise ValueError(f"Invalid question {name}")
            question_type = question.get("type")
            instructions = question.get("instructions")
            criteria = question.get("criteria")
            if type(instructions) is not str or not instructions.strip():
                raise ValueError(f"Invalid question instructions {name}")
            if question_type == "choice":
                if not isinstance(criteria, dict) or not 1 <= len(criteria) <= 255:
                    raise ValueError(f"Invalid choice criteria {name}")
                if any(type(key) is not str or not key or type(value) is not str for key, value in criteria.items()):
                    raise ValueError(f"Invalid choice criteria {name}")
            elif question_type == "score":
                if not isinstance(criteria, list) or not 2 <= len(criteria) <= 10 or any(type(item) is not str for item in criteria):
                    raise ValueError(f"Invalid score criteria {name}")
            elif question_type == "noul":
                if criteria is not None and (
                    not isinstance(criteria, dict)
                    or any(type(key) is not str or type(value) is not str for key, value in criteria.items())
                ):
                    raise ValueError(f"Invalid noul criteria {name}")
            else:
                raise ValueError(f"Unsupported Jev question type {question_type!r}")
            validated[name] = dict(question)
        return validated

    @staticmethod
    def _merge_usage(total: dict[str, Any], usage: dict[str, Any]) -> None:
        receipt_state.merge_usage(total, usage)

    def _payload(self, state: Any, questions: dict[str, Any]) -> dict[str, Any]:
        payload = {"model": self.model, "state": state, "questions": questions}
        if self.endpoint == DEFAULT_ENDPOINT:
            payload["provider"] = {"allow_fallbacks": False}
        if len(json.dumps(payload, ensure_ascii=False, allow_nan=False).encode("utf-8")) > MAX_REQUEST_BYTES:
            raise ValueError("Jev request exceeds the bounded serialized request budget")
        return payload

    def _decide_single(self, state: Any, questions: dict[str, dict[str, Any]]) -> dict:
        started = time.perf_counter()
        call_retries: dict[str, int] = {}
        retries_token = self._call_retries.set(call_retries)
        try:
            result = self._post(self._payload(state, questions))
        finally:
            self._call_retries.reset(retries_token)
        if not isinstance(result, dict):
            raise TypeError("Jev response must be an object")
        result["model"] = self._validate_resolved_model(result.get("model"))
        answers = result.get("answers")
        if not isinstance(answers, dict):
            raise TypeError("Jev response has no answers object")
        if any(type(key) is not str for key in answers) or set(answers) != set(questions):
            raise ValueError("Jev response answer keys do not exactly match the requested questions")
        validated_answers: dict[str, dict[str, Any]] = {}
        for name, question in questions.items():
            answer = answers.get(name)
            if not isinstance(answer, dict):
                raise TypeError(f"Jev response is missing answer {name}")
            question_type = question["type"]
            answer_type = answer.get("type")
            if answer_type is not None:
                if answer_type != question_type:
                    raise ValueError(f"Jev answer {name} type does not match the requested question")
                answer = {key: value for key, value in answer.items() if key != "type"}
            if question_type == "choice":
                if set(answer) != {"choice", "probabilities", "confidence"}:
                    raise ValueError(f"Jev choice {name} has unexpected response fields")
                self._validate_choice(name, answer, question["criteria"])
                validated_answers[name] = {
                    key: answer[key] for key in ("choice", "probabilities", "confidence")
                }
            elif question_type == "score":
                if set(answer) != {"score", "legend", "probabilities", "confidence"}:
                    raise ValueError(f"Jev score {name} has unexpected response fields")
                self._validate_score(name, answer, question["criteria"])
                validated_answers[name] = {
                    key: answer[key]
                    for key in ("score", "legend", "probabilities", "confidence")
                }
            else:
                if set(answer) != {"noul"}:
                    raise ValueError(f"Jev noul {name} has unexpected response fields")
                value = answer.get("noul")
                if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value) or not 0 <= value <= 1:
                    raise ValueError(f"Invalid noul answer {name}")
                validated_answers[name] = {"noul": value}
        result["answers"] = validated_answers
        result["usage"] = self._validate_usage(result.get("usage", {}))
        latency = result.get("latency_ms")
        if latency is None:
            latency = round((time.perf_counter() - started) * 1000, 1)
        elif type(latency) not in (int, float) or not math.isfinite(latency) or latency < 0:
            raise ValueError("Invalid Jev latency")
        result["latency_ms"] = float(latency)
        if call_retries:
            result["transport_retries"] = dict(call_retries)
        return result

    def decide(
        self,
        state: Any,
        questions: dict,
        *,
        public_or_sanitized_data_ack: bool = True,
    ) -> dict:
        """Return a validated typed response. Omit ack to use the standing default (on)."""
        _require_public_data_ack(public_or_sanitized_data_ack)
        validated = self._validate_questions(questions)
        batches: list[dict[str, dict[str, Any]]] = []
        current: dict[str, dict[str, Any]] = {}
        for name, question in validated.items():
            trial = {**current, name: question}
            try:
                self._payload(state, trial)
            except ValueError:
                if not current:
                    raise
                batches.append(current)
                current = {name: question}
                self._payload(state, current)
            else:
                if len(trial) > MAX_QUESTIONS_PER_REQUEST:
                    batches.append(current)
                    current = {name: question}
                else:
                    current = trial
        if current:
            batches.append(current)
        remaining = self._request_budget.get()
        allowed = MAX_DECISION_REQUESTS if remaining is None else remaining
        if len(batches) > allowed:
            raise ValueError("Jev provider-request budget exceeded")
        if remaining is not None:
            self._request_budget.set(remaining - len(batches))
        # Record each validated response as it succeeds so a later failed
        # request cannot discard earlier accounting. When a later batch fails,
        # surface the earlier observed accounting through a typed exception at
        # the terminal boundary; when the very first batch fails, preserve the
        # original exception exactly as before.
        partial: list[dict[str, Any]] = []
        calls: list[dict[str, Any]] = []
        for batch in batches:
            try:
                call = self._decide_single(state, batch)
            except Exception as exc:
                if not _DEFER_HOSTED_WARNING.get():
                    _warn_hosted_failure(hosted_error_detail(exc))
                if partial:
                    raise PartialAccountingError(
                        "Jev provider request failed after "
                        f"{len(calls)} successful batch(es)",
                        partial=partial,
                    ) from exc
                raise
            calls.append(call)
            partial.append(
                {
                    "latency_ms": call.get("latency_ms"),
                    "model": call.get("model"),
                    "request_id": call.get("request_id"),
                    "request_count": int(call.get("request_count") or 1),
                    "total_latency_ms": call.get("total_latency_ms", call.get("latency_ms")),
                    "total_usage": call.get("total_usage", call.get("usage") or {}),
                    "usage": call.get("usage") or {},
                    **(
                        {"transport_retries": dict(call["transport_retries"])}
                        if call.get("transport_retries")
                        else {}
                    ),
                }
            )
        if len(calls) == 1:
            calls[0]["request_count"] = 1
            calls[0]["total_latency_ms"] = calls[0]["latency_ms"]
            calls[0]["total_usage"] = dict(calls[0]["usage"])
            return calls[0]
        answers: dict[str, Any] = {}
        usage: dict[str, Any] = {}
        latency = 0.0
        retries: dict[str, int] = {}
        for call in calls:
            answers.update(call["answers"])
            self._merge_usage(usage, call["usage"])
            latency += call["latency_ms"]
            merge_transport_retries(retries, call.get("transport_retries"))
        combined = {
            "model": calls[-1]["model"],
            "answers": answers,
            "usage": usage,
            "latency_ms": latency,
            "request_count": len(calls),
            "total_latency_ms": latency,
            "total_usage": usage,
        }
        if retries:
            combined["transport_retries"] = retries
        return combined

    @staticmethod
    def _validate_choice(name: str, answer: dict, criteria: dict) -> None:
        if not isinstance(criteria, dict) or not criteria:
            raise ValueError(f"Jev choice {name} has no offered criteria")
        choice = answer.get("choice")
        probabilities = answer.get("probabilities")
        confidence = answer.get("confidence")
        numbers = [] if not isinstance(probabilities, dict) else [*probabilities.values(), confidence]
        valid = (
            choice in criteria
            and isinstance(probabilities, dict)
            and set(probabilities) == set(criteria)
            and all(type(value) in (int, float) and math.isfinite(value) and 0 <= value <= 1 for value in numbers)
            and abs(sum(probabilities.values()) - 1) < 0.02
            and probabilities[choice] >= max(probabilities.values()) - 1e-6
        )
        if not valid:
            raise ValueError(f"Jev choice {name} is outside the offered criteria")

    @staticmethod
    def _validate_score(name: str, answer: dict, criteria: list) -> None:
        if not isinstance(criteria, list) or not 2 <= len(criteria) <= 10:
            raise ValueError(f"Jev score {name} has invalid ordered criteria")
        score = answer.get("score")
        legend = answer.get("legend")
        probabilities = answer.get("probabilities")
        confidence = answer.get("confidence")
        if not isinstance(score, (int, float)) or isinstance(score, bool) or not math.isfinite(float(score)):
            raise ValueError(f"Invalid Jev score answer {name}")
        score_value = float(score)
        if not isinstance(confidence, (int, float)) or isinstance(confidence, bool) or not math.isfinite(float(confidence)):
            raise ValueError(f"Invalid Jev score confidence {name}")
        confidence_value = float(confidence)
        expected_keys = {str(index) for index in range(len(criteria))}
        if not (
            0 <= score_value <= len(criteria) - 1
            and isinstance(legend, dict)
            and set(legend) == expected_keys
            and isinstance(probabilities, dict)
            and set(probabilities) == expected_keys
            and all(type(value) in (int, float) and math.isfinite(float(value)) and 0 <= float(value) <= 1 for value in probabilities.values())
            and 0 <= confidence_value <= 1
            and abs(sum(float(value) for value in probabilities.values()) - 1) < 0.02
            and all(legend[str(index)] == criterion for index, criterion in enumerate(criteria))
        ):
            raise ValueError(f"Jev score {name} is outside the offered criteria")
        weighted = sum(index * float(probabilities[str(index)]) for index in range(len(criteria)))
        if abs(score_value - weighted) > 0.02:
            raise ValueError(f"Jev score {name} is inconsistent with its probability distribution")

    def close(self) -> None:
        """Close the pooled HTTP connection without affecting synthetic transports."""
        with self._connection_lock:
            self._close_connection()

    def __enter__(self) -> "DecisionClient":
        return self

    def __exit__(self, _exc_type, _exc_value, _traceback) -> None:
        self.close()

hermes_switchyard/routing.py:
"""Closed-set skill and model routing with fail-closed policy gates.

Jev is an advisory decision service. This module performs all identifier, policy,
and cost checks locally before it asks Jev for an uncalibrated fit signal. It
never loads a skill, edits a prompt, or changes the runtime model.
"""
from __future__ import annotations

import json
import math
from typing import Any

from . import receipt_state
from .client import (
    DEFAULT_OPERATION_DEADLINE_SECONDS,
    EXPECTED_MODEL,
    MAX_DECISION_REQUESTS,
    MAX_QUESTIONS_PER_REQUEST,
    MAX_REQUEST_BYTES,
    PartialAccountingError,
    merge_transport_retries,
    operation_remaining_deadline,
    request_budget_scope,
)


# These are conservative local policy thresholds. Choice confidence is output
# concentration; Noul values are intended yes/no probabilities, but calibration
# for correctness is not independently established.
DEFAULT_SKILL_CHOICE_CONFIDENCE_THRESHOLD = 0.80
DEFAULT_SKILL_NEEDS_THRESHOLD = 0.80
DEFAULT_SKILL_WINNING_PROBABILITY_THRESHOLD = 0.80
DEFAULT_MODEL_CAPABILITY_FIT_THRESHOLD = 0.80

_MODEL_REQUIREMENT_KEYS = frozenset({
    "data_classes",
    "tool_capabilities",
    "context_limit",
    "budget",
    "registry_generation",
})

_CHOICE_MAX_OPTIONS = 255  # Jev's per-Choice contract; large catalogs are reduced hierarchically.
_SKILL_PARTITION_SIZE = 200  # Leave room for an explicit no-match option.
_PARTITION_CRITERIA_BYTES = 72_000
_SKILL_NONE = "__jev_none_of_these__"
_MULTI_SKILL_PREFIX = "skill_"


def _request_size(state: Any, questions: dict[str, Any]) -> int:
    payload = {
        "model": EXPECTED_MODEL,
        "state": state,
        "questions": questions,
        "provider": {"allow_fallbacks": False},
    }
    try:
        return len(json.dumps(payload, ensure_ascii=False, allow_nan=False).encode("utf-8"))
    except (TypeError, ValueError):
        raise ValueError("Jev request contains a non-JSON value") from None


def _require_public_data_ack(acknowledged: bool = True) -> None:
    if acknowledged is not True:
        raise PermissionError(
            "public_or_sanitized_data_ack is false; this call was refused"
        )


def _bounded_number(value: Any, name: str) -> float:
    if type(value) not in (int, float) or not math.isfinite(value) or not 0 <= value <= 1:
        raise ValueError(f"{name} must be a finite number in [0, 1]")
    return float(value)


def _positive_integer(value: Any, name: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def _nonnegative_number(value: Any, name: str) -> float:
    if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
        raise ValueError(f"{name} must be a finite non-negative number")
    return float(value)


def _string_list(value: Any, name: str) -> list[str]:
    if not isinstance(value, list) or any(type(item) is not str or not item for item in value):
        raise ValueError(f"{name} must be a list of non-empty strings")
    if len(set(value)) != len(value):
        raise ValueError(f"{name} must not contain duplicate values")
    return list(value)


def _criteria(candidates: list[dict], key: str, *, max_entries: int | None = _CHOICE_MAX_OPTIONS) -> dict[str, str]:
    """Build Jev criteria without normalizing candidate identifiers."""
    if not isinstance(candidates, list) or not candidates or (max_entries is not None and len(candidates) > max_entries):
        bound = f"1 to {max_entries}" if max_entries is not None else "at least 1"
        raise ValueError(f"candidates must contain {bound} entries")
    out: dict[str, str] = {}
    for item in candidates:
        if not isinstance(item, dict):
            raise ValueError("each candidate must be an object")
        identifier = item.get(key)
        if type(identifier) is not str or not identifier:
            raise ValueError("candidate identifiers must be non-empty strings")
        if identifier != identifier.strip():
            raise ValueError("candidate identifiers must not have leading or trailing whitespace")
        if identifier in out:
            raise ValueError("candidate identifiers must be unique and exact")
        description = item.get("description", "")
        if type(description) is not str:
            raise ValueError("candidate descriptions must be strings")
        out[identifier] = description or identifier
    return out


def _choice_metrics(answer: Any, criteria: dict[str, str], name: str) -> tuple[str, float, dict[str, float]]:
    if not isinstance(answer, dict):
        raise TypeError(f"Jev response is missing answer {name}")
    if set(answer) != {"choice", "probabilities", "confidence"}:
        raise ValueError(f"Jev choice {name} has unexpected response fields")
    choice = answer.get("choice")
    probabilities = answer.get("probabilities")
    confidence = answer.get("confidence")
    if choice not in criteria or not isinstance(probabilities, dict) or set(probabilities) != set(criteria):
        raise ValueError(f"Jev choice {name} is outside the offered criteria")
    parsed = {key: _bounded_number(value, f"{name}.probabilities[{key!r}]") for key, value in probabilities.items()}
    if abs(sum(parsed.values()) - 1.0) >= 0.02:
        raise ValueError(f"Jev choice {name} probabilities do not form a distribution")
    confidence_value = _bounded_number(confidence, f"{name}.confidence")
    if parsed[choice] < max(parsed.values()) - 1e-6:
        raise ValueError(f"Jev choice {name} is not the winning choice")
    return choice, confidence_value, parsed


def _decision_metadata(result: Any) -> dict[str, Any]:
    if not isinstance(result, dict):
        raise TypeError("Jev response must be an object")
    answers = result.get("answers")
    if not isinstance(answers, dict):
        raise TypeError("Jev response has no answers object")
    usage = result.get("usage") or {}
    if not isinstance(usage, dict):
        raise TypeError("Jev response usage must be an object")
    bounded_usage = receipt_state.safe_usage(usage)
    total_usage = result.get("total_usage", usage)
    if not isinstance(total_usage, dict):
        raise TypeError("Jev response total_usage must be an object")
    metadata = {
        "model": result.get("model"),
        "request_id": result.get("request_id"),
        "latency_ms": result.get("latency_ms"),
        "usage": bounded_usage,
        "request_count": int(result.get("request_count") or 1),
        "total_latency_ms": result.get("total_latency_ms", result.get("latency_ms")),
        "total_usage": receipt_state.safe_usage(total_usage),
    }
    retries: dict[str, int] = {}
    merge_transport_retries(retries, result.get("transport_retries"))
    if retries:
        metadata["transport_retries"] = retries
    return metadata


def _aggregate_metadata(calls: list[dict[str, Any]]) -> dict[str, Any]:
    usage: dict[str, Any] = {}
    retries: dict[str, int] = {}
    latency = 0.0
    request_count = 0
    for call in calls:
        value = call.get("latency_ms")
        if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0:
            latency += float(value)
        request_count += int(call.get("request_count") or 1)
        receipt_state.merge_usage(usage, call.get("usage") or {})
        merge_transport_retries(retries, call.get("transport_retries"))
    aggregate: dict[str, Any] = {
        "total_latency_ms": latency,
        "total_usage": usage,
        "request_count": request_count,
    }
    if retries:
        aggregate["transport_retries"] = retries
    return aggregate


def _skill_request_parts(
    chunk: list[dict],
    *,
    task: str,
    total_count: int,
    partition: int,
    include_needs_skill: bool,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    criteria = _criteria(chunk, "name", max_entries=None)
    if _SKILL_NONE in criteria:
        raise ValueError(f"candidate name {_SKILL_NONE!r} is reserved")
    criteria[_SKILL_NONE] = "No candidate in this partition materially fits the task"
    name = f"skill_chunk_{partition}"
    questions: dict[str, dict[str, Any]] = {
        name: {
            "type": "choice",
            "instructions": (
                "Which offered skill best matches this task? Choose the none option when no skill "
                "in this partition adds material value. The result is advisory."
            ),
            "criteria": criteria,
        }
    }
    if include_needs_skill:
        questions["needs_skill"] = {
            "type": "noul",
            "instructions": "Does this task need one of the offered skills?",
            "criteria": {
                "true": "A candidate provides specialized procedure or constraints needed for the task",
                "false": "The task is simple or none of the candidates adds material value",
            },
        }
    state = {
        "task": task,
        "candidate_count": total_count,
        "partition": partition,
        "skills": chunk,
    }
    return state, questions


def _skill_chunks(candidates: list[dict], *, task: str = "") -> list[list[dict]]:
    chunks: list[list[dict]] = []
    current: list[dict] = []
    for candidate in candidates:
        while True:
            partition = len(chunks)
            trial = current + [candidate]
            state, questions = _skill_request_parts(
                trial,
                task=task,
                total_count=len(candidates),
                partition=partition,
                include_needs_skill=partition == 0,
            )
            criteria_size = len(
                json.dumps(
                    questions[f"skill_chunk_{partition}"]["criteria"],
                    ensure_ascii=False,
                    allow_nan=False,
                ).encode("utf-8")
            )
            too_large = _request_size(state, questions) > MAX_REQUEST_BYTES
            if not current and too_large:
                raise ValueError("a single skill candidate exceeds the bounded serialized request budget")
            if current and (
                len(trial) > _SKILL_PARTITION_SIZE
                or criteria_size > _PARTITION_CRITERIA_BYTES
                or too_large
            ):
                chunks.append(current)
                current = []
                continue
            current = trial
            break
    if current:
        chunks.append(current)
    return chunks


def _small_skill_request_parts(
    task: str, candidates: list[dict]
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    criteria = _criteria(candidates, "name")
    questions = {
        "skill": {
            "type": "choice",
            "instructions": (
                "Which available skill best matches this task? Choose only one offered candidate. "
                "The result is advisory and must not load a skill automatically."
            ),
            "criteria": criteria,
        },
        "needs_skill": {
            "type": "noul",
            "instructions": (
                "Does this task need one of the offered skills? Answer the literal yes/no "
                "question using the Noul probability primitive."
            ),
            "criteria": {
                "true": "A candidate provides specialized procedure or constraints needed for the task",
                "false": "The task is simple or none of the candidates adds material value",
            },
        },
    }
    state = {
        "task": task,
        "skills": [{"name": key, "description": value} for key, value in criteria.items()],
    }
    return state, questions


def _select_skill_small(
    *,
    task: str,
    candidates: list[dict],
    client: Any,
    choice_confidence_threshold: float = DEFAULT_SKILL_CHOICE_CONFIDENCE_THRESHOLD,
    needs_skill_threshold: float = DEFAULT_SKILL_NEEDS_THRESHOLD,
    winning_probability_threshold: float = DEFAULT_SKILL_WINNING_PROBABILITY_THRESHOLD,
    public_or_sanitized_data_ack: bool = True,
) -> dict:
    """Return an advisory skill choice or an explicit abstention.

    Thresholds are bounded local policy values and are deliberately not presented
    as calibrated probabilities. The caller remains responsible for deciding
    whether to load a skill; this function never performs that mutation.
    """
    _require_public_data_ack(public_or_sanitized_data_ack)
    thresholds = {
        "choice_confidence": _bounded_number(choice_confidence_threshold, "choice_confidence_threshold"),
        "needs_skill": _bounded_number(needs_skill_threshold, "needs_skill_threshold"),
        "winning_probability": _bounded_number(winning_probability_threshold, "winning_probability_threshold"),
    }
    state, questions = _small_skill_request_parts(task, candidates)
    criteria = questions["skill"]["criteria"]
    operation_remaining_deadline()
    result = client.decide(
        state,
        questions,
        public_or_sanitized_data_ack=True,
    )
    operation_remaining_deadline()
    metadata = _decision_metadata(result)
    answers = result["answers"]
    if set(answers) != set(questions):
        raise ValueError("Jev skill answer keys do not exactly match the request")
    selected_candidate, confidence, probabilities = _choice_metrics(answers.get("skill"), criteria, "skill")
    needs_answer = answers.get("needs_skill")
    if not isinstance(needs_answer, dict):
        raise TypeError("Jev response is missing answer needs_skill")
    needs_score = _bounded_number(needs_answer.get("noul"), "needs_skill.noul")
    reasons: list[str] = []
    if confidence < thresholds["choice_confidence"]:
        reasons.append("choice_confidence_below_threshold")
    if needs_score < thresholds["needs_skill"]:
        reasons.append("needs_skill_below_threshold")
    winning_probability = probabilities[selected_candidate]
    if winning_probability < thresholds["winning_probability"]:
        reasons.append("winning_probability_below_threshold")
    selected = None if reasons else selected_candidate
    return {
        "status": "selected" if selected is not None else "abstained",
        "selected": selected,
        "abstention_reason": ";".join(reasons) if reasons else None,
        "needs_skill_noul": needs_score,
        # Compatibility name retained as a score label, not a calibrated probability claim.
        "needs_skill_probability": needs_score,
        "confidence": confidence,
        "winning_probability": winning_probability,
        "probabilities": probabilities,
        "thresholds": thresholds,
        "candidate_count": len(candidates),
        "offered_count": len(candidates),
        "excluded_count": 0,
        "shortlist_policy": "complete_candidate_set",
        **metadata,
    }


def _skill_partition_winners(
    *,
    task: str,
    candidates: list[dict],
    client: Any,
    include_needs_skill: bool,
) -> tuple[list[dict], list[dict[str, Any]], float | None]:
    """Evaluate every bounded partition and retain one finalist from each."""
    if not candidates:
        return [], [], None
    winners: list[dict] = []
    metadata: list[dict[str, Any]] = []
    needs_score: float | None = None
    for partition, chunk in enumerate(_skill_chunks(candidates, task=task)):
        state, questions = _skill_request_parts(
            chunk,
            task=task,
            total_count=len(candidates),
            partition=partition,
            include_needs_skill=include_needs_skill and partition == 0,
        )
        name = f"skill_chunk_{partition}"
        criteria = questions[name]["criteria"]
        try:
            operation_remaining_deadline()
            result = client.decide(
                state,
                questions,
                public_or_sanitized_data_ack=True,
            )
            operation_remaining_deadline()
        except PartialAccountingError as exc:
            if metadata:
                raise PartialAccountingError(
                    "Jev skill partitioning failed after earlier successful partition(s)",
                    partial=metadata + exc.partial,
                ) from exc
            raise
        except Exception as exc:
            # The aggregate budget remains an operation-level signal, not a
            # partition result, so budget exhaustion is re-raised verbatim.
            if isinstance(exc, ValueError) and "budget exceeded" in str(exc):
                raise
            if metadata:
                raise PartialAccountingError(
                    "Jev skill partitioning failed after earlier successful partition(s)",
                    partial=metadata,
                ) from exc
            raise
        answers = result.get("answers") if isinstance(result, dict) else None
        if not isinstance(answers, dict):
            raise TypeError("Jev large-skill response has no answers object")
        if set(answers) != set(questions):
            raise ValueError("Jev large-skill answer keys do not exactly match the partition")
        choice, _confidence, _probabilities = _choice_metrics(answers.get(name), criteria, name)
        if choice != _SKILL_NONE:
            winners.append(next(item for item in chunk if item["name"] == choice))
        metadata.append(_decision_metadata(result))
        if "needs_skill" in questions:
            needs = answers.get("needs_skill")
            if not isinstance(needs, dict):
                raise TypeError("Jev large-skill response is missing needs_skill")
            needs_score = _bounded_number(needs.get("noul"), "needs_skill.noul")
    return winners, metadata, needs_score


def _skill_direct_request_fits(task: str, candidates: list[dict]) -> bool:
    state, questions = _small_skill_request_parts(task, candidates)
    return _request_size(state, questions) <= MAX_REQUEST_BYTES


def _select_skill_impl(
    *,
    task: str,
    candidates: list[dict],
    client: Any,
    choice_confidence_threshold: float = DEFAULT_SKILL_CHOICE_CONFIDENCE_THRESHOLD,
    needs_skill_threshold: float = DEFAULT_SKILL_NEEDS_THRESHOLD,
    winning_probability_threshold: float = DEFAULT_SKILL_WINNING_PROBABILITY_THRESHOLD,
    public_or_sanitized_data_ack: bool = True,
) -> dict:
    """Select a skill, reducing arbitrarily large catalogs through Jev fan-out.

    A normal Choice remains one request for small catalogs. Larger catalogs are
    searched in full through partition questions and recursive reduction, then a
    final bounded Choice applies the same policy thresholds.
    """
    if not isinstance(candidates, list) or not candidates:
        return _select_skill_small(
            task=task, candidates=candidates, client=client,
            choice_confidence_threshold=choice_confidence_threshold,
            needs_skill_threshold=needs_skill_threshold,
            winning_probability_threshold=winning_probability_threshold,
            public_or_sanitized_data_ack=public_or_sanitized_data_ack,
        )
    if len(candidates) <= _CHOICE_MAX_OPTIONS and _skill_direct_request_fits(task, candidates):
        return _select_skill_small(
            task=task, candidates=candidates, client=client,
            choice_confidence_threshold=choice_confidence_threshold,
            needs_skill_threshold=needs_skill_threshold,
            winning_probability_threshold=winning_probability_threshold,
            public_or_sanitized_data_ack=public_or_sanitized_data_ack,
        )

    _require_public_data_ack(public_or_sanitized_data_ack)
    # Validate the complete catalog before any network call. This prevents a
    # malformed tail from being hidden by partitioning.
    _criteria(candidates, "name", max_entries=None)
    pool = list(candidates)
    rounds = 0
    reduction_metadata: list[dict[str, Any]] = []
    first_needs_score: float | None = None
    while len(pool) > _CHOICE_MAX_OPTIONS or not _skill_direct_request_fits(task, pool):
        try:
            pool, metadata, needs_score = _skill_partition_winners(
                task=task,
                candidates=pool,
                client=client,
                include_needs_skill=rounds == 0,
            )
        except PartialAccountingError as exc:
            if reduction_metadata:
                raise PartialAccountingError(
                    "Jev skill reduction failed after earlier successful round(s)",
                    partial=reduction_metadata + exc.partial,
                ) from exc
            raise
        rounds += 1
        reduction_metadata.extend(metadata)
        if first_needs_score is None:
            first_needs_score = needs_score
        if not pool:
            thresholds = {
                "choice_confidence": _bounded_number(choice_confidence_threshold, "choice_confidence_threshold"),
                "needs_skill": _bounded_number(needs_skill_threshold, "needs_skill_threshold"),
                "winning_probability": _bounded_number(winning_probability_threshold, "winning_probability_threshold"),
            }
            needs = first_needs_score
            return {
                "status": "abstained", "selected": None,
                "abstention_reason": "no_partition_candidate",
                "needs_skill_noul": needs, "needs_skill_probability": needs,
                "confidence": 0.0, "winning_probability": 0.0,
                "probabilities": {}, "thresholds": thresholds,
                "candidate_count": len(candidates), "reduction_rounds": rounds,
                "offered_count": len(candidates), "excluded_count": 0,
                "shortlist_policy": "full_partition_fan_out",
                "reduction_metadata": reduction_metadata,
                **_aggregate_metadata(reduction_metadata),
            }
    try:
        result = _select_skill_small(
            task=task, candidates=pool, client=client,
            choice_confidence_threshold=choice_confidence_threshold,
            needs_skill_threshold=needs_skill_threshold,
            winning_probability_threshold=winning_probability_threshold,
            public_or_sanitized_data_ack=True,
        )
    except PartialAccountingError as exc:
        if reduction_metadata:
            raise PartialAccountingError(
                "Jev final skill selection failed after earlier successful round(s)",
                partial=reduction_metadata + exc.partial,
            ) from exc
        raise
    except Exception as exc:
        if reduction_metadata:
            raise PartialAccountingError(
                "Jev final skill selection failed after earlier successful round(s)",
                partial=reduction_metadata,
            ) from exc
        raise
    result["candidate_count"] = len(candidates)
    result["offered_count"] = len(candidates)
    result["excluded_count"] = 0
    result["shortlist_policy"] = "full_partition_fan_out"
    result["reduction_rounds"] = rounds
    result["reduction_metadata"] = reduction_metadata
    final_metadata = {
        "model": result.get("model"),
        "request_id": result.get("request_id"),
        "latency_ms": result.get("latency_ms"),
        "usage": result.get("usage") or {},
        "request_count": int(result.get("request_count") or 1),
        "transport_retries": result.get("transport_retries"),
    }
    result.update(_aggregate_metadata(reduction_metadata + [final_metadata]))
    return result


def select_skill(
    *, task: str, candidates: list[dict], client: Any,
    choice_confidence_threshold: float = DEFAULT_SKILL_CHOICE_CONFIDENCE_THRESHOLD,
    needs_skill_threshold: float = DEFAULT_SKILL_NEEDS_THRESHOLD,
    winning_probability_threshold: float = DEFAULT_SKILL_WINNING_PROBABILITY_THRESHOLD,
    public_or_sanitized_data_ack: bool = True,
    deadline_seconds: float = DEFAULT_OPERATION_DEADLINE_SECONDS,
) -> dict:
    with request_budget_scope(
        client, MAX_DECISION_REQUESTS, deadline_seconds=deadline_seconds
    ):
        return _select_skill_impl(
            task=task, candidates=candidates, client=client,
            choice_confidence_threshold=choice_confidence_threshold,
            needs_skill_threshold=needs_skill_threshold,
            winning_probability_threshold=winning_probability_threshold,
            public_or_sanitized_data_ack=public_or_sanitized_data_ack,
        )


def _multi_skill_batch_questions(
    batch: list[dict], *, offset: int, task: str
) -> dict[str, dict[str, Any]]:
    """Build the exact multi-skill questions sent to Jev for one batch.

    Every question carries its candidate's exact identifier and description, so
    the caller can size a request using the same structure it will serialize.
    """
    return {
        f"{_MULTI_SKILL_PREFIX}{offset + index}": {
            "type": "noul",
            "instructions": (
                "Does this exact offered skill materially help with the task? "
                f"Candidate identifier: {item['name']}. "
                f"Candidate description: {item.get('description', '')}"
            ),
            "criteria": {"true": "The skill helps", "false": "The skill does not help"},
        }
        for index, item in enumerate(batch)
    }


def _multi_skill_batches(candidates: list[dict], *, task: str) -> list[list[dict]]:
    batches: list[list[dict]] = []
    current: list[dict] = []
    offset = 0
    for candidate in candidates:
        while True:
            trial = current + [candidate]
            questions = _multi_skill_batch_questions(
                trial, offset=offset, task=task
            )
            too_large = _request_size(
                {"task": task, "skills": trial}, questions
            ) > MAX_REQUEST_BYTES
            if not current and too_large:
                raise ValueError(
                    "a single skill candidate exceeds the bounded serialized request budget"
                )
            if current and (len(trial) > MAX_QUESTIONS_PER_REQUEST or too_large):
                batches.append(current)
                offset += len(current)
                current = []
                continue
            current = trial
            break
    if current:
        batches.append(current)
    return batches


def select_skills(
    *,
    task: str,
    candidates: list[dict],
    client: Any,
    selection_threshold: float = DEFAULT_SKILL_NEEDS_THRESHOLD,
    max_selections: int | None = None,
    public_or_sanitized_data_ack: bool = True,
    deadline_seconds: float = DEFAULT_OPERATION_DEADLINE_SECONDS,
) -> dict:
    """Return a typed list of advisory skill identifiers.

    Multi-selection is deliberately separate from ``select_skill``: each exact
    candidate receives an independent Noul fit score, and no skill is loaded.
    """
    _require_public_data_ack(public_or_sanitized_data_ack)
    if not isinstance(candidates, list) or not candidates:
        raise ValueError("candidates must contain at least 1 entry")
    _criteria(candidates, "name", max_entries=None)
    threshold = _bounded_number(selection_threshold, "selection_threshold")
    if max_selections is not None and (
        type(max_selections) is not int or not 1 <= max_selections <= len(candidates)
    ):
        raise ValueError("max_selections must be a positive bound within the candidate set")
    with request_budget_scope(
        client, MAX_DECISION_REQUESTS, deadline_seconds=deadline_seconds
    ):
        scores: dict[str, float] = {}
        metadata: list[dict[str, Any]] = []
        offset = 0
        for batch in _multi_skill_batches(candidates, task=task):
            # Reuse the exact shared construction so the size checked during
            # batching equals the payload actually sent to Jev.
            questions = _multi_skill_batch_questions(batch, offset=offset, task=task)
            operation_remaining_deadline()
            try:
                result = client.decide(
                    {"task": task, "skills": batch},
                    questions,
                    public_or_sanitized_data_ack=True,
                )
            except PartialAccountingError as exc:
                # Outer-batch boundary: earlier outer batches already produced
                # accounting this loop owns; merge before surfacing so a later
                # wire failure cannot discard earlier successful calls.
                if metadata:
                    raise PartialAccountingError(
                        "Jev multi-skill scoring failed after earlier successful batch(es)",
                        partial=metadata + list(exc.partial),
                    ) from exc
                raise
            except Exception as exc:
                if metadata:
                    raise PartialAccountingError(
                        "Jev multi-skill scoring failed after earlier successful batch(es)",
                        partial=metadata,
                    ) from exc
                raise
            operation_remaining_deadline()
            metadata.append(_decision_metadata(result))
            answers = result.get("answers") if isinstance(result, dict) else None
            if not isinstance(answers, dict):
                raise TypeError("Jev multi-skill response has no answers object")
            expected_names = {
                f"{_MULTI_SKILL_PREFIX}{offset + index}"
                for index in range(len(batch))
            }
            if set(answers) != expected_names:
                raise ValueError("Jev multi-skill answer keys do not exactly match the batch")
            for index, candidate in enumerate(batch):
                name = f"{_MULTI_SKILL_PREFIX}{offset + index}"
                scores[candidate["name"]] = _noul_score(answers.get(name), name)
            offset += len(batch)
    selected = [
        candidate["name"]
        for candidate in candidates
        if scores[candidate["name"]] >= threshold
    ]
    selected.sort(key=lambda name: (-scores[name], next(
        index for index, item in enumerate(candidates) if item["name"] == name
    )))
    if max_selections is not None:
        selected = selected[:max_selections]
    aggregate = _aggregate_metadata(metadata)
    return {
        "status": "selected" if selected else "abstained",
        "selected": selected,
        "scores": scores,
        "selection_threshold": threshold,
        "max_selections": max_selections,
        "candidate_count": len(candidates),
        "shortlist_policy": "independent_multi_skill_scores",
        "abstention_reason": None if selected else "no_skill_met_selection_threshold",
        **aggregate,
    }


def _model_requirements(requirements: dict) -> dict[str, Any]:
    if not isinstance(requirements, dict):
        raise ValueError("requirements must be an object")
    unknown = set(requirements) - _MODEL_REQUIREMENT_KEYS
    if unknown:
        raise ValueError(f"unsupported model requirement fields: {sorted(unknown)!r}")
    parsed: dict[str, Any] = {}
    if "data_classes" in requirements:
        parsed["data_classes"] = _string_list(requirements["data_classes"], "requirements.data_classes")
    if "tool_capabilities" in requirements:
        parsed["tool_capabilities"] = _string_list(
            requirements["tool_capabilities"], "requirements.tool_capabilities"
        )
    if "context_limit" in requirements:
        parsed["context_limit"] = _positive_integer(requirements["context_limit"], "requirements.context_limit")
    if "budget" in requirements:
        parsed["budget"] = _nonnegative_number(requirements["budget"], "requirements.budget")
    if "registry_generation" in requirements:
        parsed["registry_generation"] = _positive_integer(
            requirements["registry_generation"], "requirements.registry_generation"
        )
    return parsed


def _model_candidates(candidates: list[dict]) -> list[dict[str, Any]]:
    if not isinstance(candidates, list) or not candidates:
        raise ValueError("candidates must contain at least 1 entry")
    # Validate exact identifiers and common descriptions first.
    _criteria(candidates, "id", max_entries=None)
    records: list[dict[str, Any]] = []
    for position, item in enumerate(candidates):
        identifier = item["id"]
        approved = item.get("approved")
        if type(approved) is not bool:
            raise ValueError(f"candidate {identifier!r} requires an explicit boolean approved field")
        description = item.get("description", "")
        if type(description) is not str:
            raise ValueError(f"candidate {identifier!r} description must be a string")
        allowed = None
        if "data_classes_allowed" in item:
            allowed = _string_list(item["data_classes_allowed"], f"candidate {identifier!r}.data_classes_allowed")
        capabilities = None
        if "tool_capabilities" in item:
            capabilities = _string_list(item["tool_capabilities"], f"candidate {identifier!r}.tool_capabilities")
        context_limit = None
        if "context_limit" in item:
            context_limit = _positive_integer(item["context_limit"], f"candidate {identifier!r}.context_limit")
        cost = None
        if "cost" in item:
            cost = _nonnegative_number(item["cost"], f"candidate {identifier!r}.cost")
        registry_generation = None
        if "registry_generation" in item:
            registry_generation = _positive_integer(
                item["registry_generation"], f"candidate {identifier!r}.registry_generation"
            )
        records.append({
            "id": identifier,
            "description": description,
            "approved": approved,
            "data_classes_allowed": allowed,
            "tool_capabilities": capabilities,
            "context_limit": context_limit,
            "cost": cost,
            "registry_generation": registry_generation,
            "position": position,
        })
    return records


def _eligible_model_candidates(
    candidates: list[dict[str, Any]], requirements: dict[str, Any]
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    eligible: list[dict[str, Any]] = []
    excluded: list[dict[str, Any]] = []
    required_classes = set(requirements.get("data_classes", []))
    required_tools = set(requirements.get("tool_capabilities", []))
    required_context = requirements.get("context_limit")
    budget = requirements.get("budget")
    required_generation = requirements.get("registry_generation")
    for candidate in candidates:
        reasons: list[str] = []
        if candidate["approved"] is not True:
            reasons.append("not_approved")
        if candidate["cost"] is None:
            # A cost is always required because the final choice is code-owned and
            # must be provably the cheapest qualified candidate.
            reasons.append("missing_cost")
        if required_generation is not None:
            generation = candidate.get("registry_generation")
            if generation is None or generation != required_generation:
                reasons.append("stale_registry")
        if required_classes:
            allowed = candidate["data_classes_allowed"]
            if allowed is None:
                reasons.append("missing_data_classes_allowed")
            elif not required_classes.issubset(allowed):
                reasons.append("data_class_not_allowed")
        if required_tools:
            capabilities = candidate["tool_capabilities"]
            if capabilities is None:
                reasons.append("missing_tool_capabilities")
            elif not required_tools.issubset(capabilities):
                reasons.append("tool_capability_missing")
        if required_context is not None:
            context_limit = candidate["context_limit"]
            if context_limit is None:
                reasons.append("missing_context_limit")
            elif context_limit < required_context:
                reasons.append("context_limit_too_small")
        if budget is not None and candidate["cost"] is not None and candidate["cost"] > budget:
            reasons.append("over_budget")
        if reasons:
            excluded.append({"id": candidate["id"], "reasons": reasons})
        else:
            eligible.append(candidate)
    return eligible, excluded


def _noul_score(answer: Any, name: str) -> float:
    if not isinstance(answer, dict):
        raise TypeError(f"Jev response is missing answer {name}")
    if set(answer) != {"noul"}:
        raise ValueError(f"Jev noul {name} has unexpected response fields")
    return _bounded_number(answer.get("noul"), f"{name}.noul")


def _route_metadata(result: Any) -> dict[str, Any]:
    metadata = _decision_metadata(result)
    if metadata["usage"].get("cost") is not None:
        metadata["usage"] = dict(metadata["usage"])
        metadata["usage"]["cost"] = _nonnegative_number(metadata["usage"]["cost"], "usage.cost")
    return metadata


def _model_request_parts(
    batch: list[dict[str, Any]],
    *,
    task: str = "",
    requirements: dict[str, Any] | None = None,
    offset: int = 0,
) -> tuple[dict[str, Any], dict[str, Any]]:
    questions: dict[str, dict[str, Any]] = {}
    eligible_state: list[dict[str, Any]] = []
    for index, candidate in enumerate(batch):
        question_name = f"fit_{offset + index}"
        questions[question_name] = {
            "type": "noul",
            "instructions": (
                f"Does eligible_candidates[{index}] with id {candidate['id']!r} have the capability fit "
                "for the task? Answer the literal yes/no question using the Noul probability primitive."
            ),
            "criteria": {"true": "The candidate capabilities fit the task", "false": "They do not"},
        }
        eligible_state.append({
            "question": question_name,
            "id": candidate["id"],
            "description": candidate["description"],
            "data_classes_allowed": candidate["data_classes_allowed"],
            "tool_capabilities": candidate["tool_capabilities"],
            "context_limit": candidate["context_limit"],
            "cost": candidate["cost"],
        })
    state = {"task": task, "requirements": requirements or {}, "eligible_candidates": eligible_state}
    return state, questions


def _model_batches(
    candidates: list[dict[str, Any]],
    *,
    task: str = "",
    requirements: dict[str, Any] | None = None,
) -> list[list[dict[str, Any]]]:
    batches: list[list[dict[str, Any]]] = []
    current: list[dict[str, Any]] = []
    offset = 0
    for candidate in candidates:
        while True:
            trial = current + [candidate]
            state, questions = _model_request_parts(
                trial, task=task, requirements=requirements, offset=offset
            )
            criteria_size = len(
                json.dumps(
                    state["eligible_candidates"], ensure_ascii=False, allow_nan=False
                ).encode("utf-8")
            )
            too_large = _request_size(state, questions) > MAX_REQUEST_BYTES
            if not current and too_large:
                raise ValueError("a single model candidate exceeds the bounded serialized request budget")
            if current and (
                len(trial) > 200
                or criteria_size > _PARTITION_CRITERIA_BYTES
                or too_large
            ):
                batches.append(current)
                offset += len(current)
                current = []
                continue
            current = trial
            break
    if current:
        batches.append(current)
    return batches


def _route_model_impl(
    *,
    task: str,
    candidates: list[dict],
    requirements: dict,
    client: Any,
    capability_fit_threshold: float = DEFAULT_MODEL_CAPABILITY_FIT_THRESHOLD,
    public_or_sanitized_data_ack: bool = True,
) -> dict:
    """Filter model candidates locally, ask Jev for fit scores, then pick cheapest.

    Policy metadata is never inferred from descriptions. No runtime model is
    changed and no automatic fallback is attempted when the route abstains.
    """
    _require_public_data_ack(public_or_sanitized_data_ack)
    fit_threshold = _bounded_number(capability_fit_threshold, "capability_fit_threshold")
    parsed_requirements = _model_requirements(requirements)
    records = _model_candidates(candidates)
    eligible, excluded = _eligible_model_candidates(records, parsed_requirements)
    base = {
        "status": "abstained",
        "selected": None,
        "eligible_candidates": [candidate["id"] for candidate in eligible],
        "excluded_candidates": excluded,
        "qualified_candidates": [],
        "capability_fit_scores": {},
        "capability_fit_threshold": fit_threshold,
        "selection_policy": "cheapest qualified candidate; advisory only; runtime model is unchanged",
        "model": None,
        "latency_ms": None,
        "usage": {},
    }
    if not eligible:
        if excluded and all("stale_registry" in item["reasons"] for item in excluded):
            base["abstention_reason"] = "stale_registry"
        else:
            base["abstention_reason"] = "no_eligible_candidates"
        return base

    scores: dict[str, float] = {}
    qualified: list[dict[str, Any]] = []
    call_metadata: list[dict[str, Any]] = []
    global_offset = 0
    for batch in _model_batches(
        eligible, task=task, requirements=parsed_requirements
    ):
        eligible_state, questions = _model_request_parts(
            batch, task=task, requirements=parsed_requirements, offset=global_offset
        )
        operation_remaining_deadline()
        try:
            result = client.decide(
                eligible_state,
                questions,
                public_or_sanitized_data_ack=True,
            )
        except PartialAccountingError as exc:
            # Outer-batch boundary: keep accounting from earlier routing
            # batches alongside the failing call's internal partial ledger.
            if call_metadata:
                raise PartialAccountingError(
                    "Jev model routing failed after earlier successful batch(es)",
                    partial=call_metadata + list(exc.partial),
                ) from exc
            raise
        except Exception as exc:
            if call_metadata:
                raise PartialAccountingError(
                    "Jev model routing failed after earlier successful batch(es)",
                    partial=call_metadata,
                ) from exc
            raise
        operation_remaining_deadline()
        call_metadata.append(_route_metadata(result))
        answers = result["answers"]
        expected_names = {f"fit_{global_offset + index}" for index in range(len(batch))}
        if set(answers) != expected_names:
            raise ValueError("Jev model-routing answer keys do not exactly match the batch")
        for index, candidate in enumerate(batch):
            name = f"fit_{global_offset + index}"
            score = _noul_score(answers.get(name), name)
            scores[candidate["id"]] = score
            if score >= fit_threshold:
                qualified.append(candidate)
        global_offset += len(batch)
    if call_metadata:
        base.update(call_metadata[-1])
        base.update(_aggregate_metadata(call_metadata))
    base["capability_fit_scores"] = scores
    base["qualified_candidates"] = [candidate["id"] for candidate in qualified]
    if not qualified:
        base["abstention_reason"] = "no_candidate_met_capability_fit_threshold"
        return base
    selected = min(qualified, key=lambda candidate: (candidate["cost"], candidate["position"]))
    base.update({"status": "selected", "selected": selected["id"], "abstention_reason": None})
    return base


def route_model(
    *, task: str, candidates: list[dict], requirements: dict, client: Any,
    capability_fit_threshold: float = DEFAULT_MODEL_CAPABILITY_FIT_THRESHOLD,
    public_or_sanitized_data_ack: bool = True,
    deadline_seconds: float = DEFAULT_OPERATION_DEADLINE_SECONDS,
) -> dict:
    with request_budget_scope(
        client, MAX_DECISION_REQUESTS, deadline_seconds=deadline_seconds
    ):
        return _route_model_impl(
            task=task, candidates=candidates, requirements=requirements, client=client,
            capability_fit_threshold=capability_fit_threshold,
            public_or_sanitized_data_ack=public_or_sanitized_data_ack,
        )
